CREATE TABLE t1(n INT, log INT); WITH RECURSIVE c(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM c WHERE i<31) INSERT INTO t1 SELECT i,(i>1)+(i>2)+(i>4)+(i>8)+(i>16) FROM c; CREATE TABLE t2 AS SELECT log AS 'x',count(*) AS 'y' FROM t1 GROUP BY log; CREATE TABLE t3(a TEXT,b FLOAT,c TEXT); INSERT INTO t3 VALUES(1,1.1,'1.1'),(2,1.10,'1.10'),(3,1.10,'1.1'),(4,1.1,'1.10'),(5,1.2,'1.2'),(6,1.3,'1.3');